import * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import type {
  Hole,
  ObstacleDescriptor,
  SurfaceDescriptor,
  SurfaceMaterial,
  TransformDescriptor,
} from '../courses/types';

const SURFACE_COLORS: Record<SurfaceMaterial, number> = {
  green: 0x4aa657,
  rough: 0x6b7d3a,
  sand: 0xe3d09a,
  ice: 0xbfe9ff,
  wood: 0xa9713f,
  stone: 0x8d8d8d,
  metal: 0xc0c6cc,
};

const OBSTACLE_COLORS: Record<ObstacleDescriptor['type'], number> = {
  wall: 0x9aa0a6,
  bumper: 0xe2573f,
  pillar: 0x7f6a55,
  block: 0x6f7b8a,
  spinner: 0xf2b134,
  windmill: 0xf2f2f2,
  gate: 0x4f86c6,
  platform: 0x8f6fb5,
  water: 0x2f7fd0,
  void: 0x1b1b24,
  'reset-zone': 0xd45fa0,
  'sliding-wall': 0x7d8794,
  door: 0x5f7f9f,
  pendulum: 0xd8b94a,
  teleporter: 0x9b5de5,
  fan: 0x67e8f9,
  conveyor: 0xa3a3a3,
  'spring-pad': 0xf472b6,
  'boost-pad': 0x22d3ee,
  'jump-pad': 0x84cc16,
  'gravity-zone': 0x6366f1,
  'magnet-zone': 0xf59e0b,
  lava: 0xff5722,
};

const CUP_COLOR = 0x14181d;
const UNIT_SCALE: Vec3 = { x: 1, y: 1, z: 1 };

/** Hazards the ball rolls through: they are triggers, so they must not look like blocks. */
const HAZARD_TYPES = new Set<ObstacleDescriptor['type']>(['water', 'lava', 'void', 'reset-zone']);
/** Force fields keep their authored volume, but only as a translucent haze. */
const FIELD_TYPES = new Set<ObstacleDescriptor['type']>(['gravity-zone', 'magnet-zone']);

/** Thickness of the spill a hazard paints on the course. */
export const HAZARD_SLAB_HEIGHT = 0.06;
/** Gap between the spill and the surface under it, so the two faces never z-fight. */
export const HAZARD_SLAB_LIFT = 0.01;
export const HAZARD_OPACITY = 0.78;
export const FIELD_OPACITY = 0.18;
const SENSOR_EMISSIVE_INTENSITY = 0.55;

export interface HoleSceneResult {
  group: THREE.Group;
  meshCount: number;
  dispose(): void;
}

interface Placement {
  transform: TransformDescriptor;
  size: Vec3;
}

function scaledSize(placement: Placement): Vec3 {
  const scale = placement.transform.scale ?? UNIT_SCALE;
  return {
    x: Math.abs(placement.size.x * scale.x),
    y: Math.abs(placement.size.y * scale.y),
    z: Math.abs(placement.size.z * scale.z),
  };
}

function overlapsHorizontally(a: Placement, b: Placement): boolean {
  const sizeA = scaledSize(a);
  const sizeB = scaledSize(b);
  return (
    Math.abs(a.transform.position.x - b.transform.position.x) < (sizeA.x + sizeB.x) / 2 &&
    Math.abs(a.transform.position.z - b.transform.position.z) < (sizeA.z + sizeB.z) / 2
  );
}

/**
 * Height a hazard is painted at: the highest surface crossing its trigger volume, so lava reads as a
 * pool on the fairway instead of a wall. A hazard over a gap keeps the top of its own volume.
 */
export function hazardSurfaceTop(hole: Hole, obstacle: ObstacleDescriptor): number {
  const size = scaledSize(obstacle);
  const bottom = obstacle.transform.position.y - size.y / 2;
  const top = obstacle.transform.position.y + size.y / 2;
  let support = Number.NEGATIVE_INFINITY;
  for (const surface of hole.surfaces) {
    if (!overlapsHorizontally(surface, obstacle)) continue;
    const surfaceTop = surface.transform.position.y + scaledSize(surface).y / 2;
    if (surfaceTop < bottom || surfaceTop > top) continue;
    if (surfaceTop > support) support = surfaceTop;
  }
  return support === Number.NEGATIVE_INFINITY ? top : support;
}

function applyTransform(mesh: THREE.Mesh, transform: TransformDescriptor, size: Vec3): void {
  mesh.position.set(transform.position.x, transform.position.y, transform.position.z);
  const rotation = transform.rotation;
  if (rotation) {
    mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
  }
  const scale = transform.scale ?? UNIT_SCALE;
  mesh.scale.set(size.x * scale.x, size.y * scale.y, size.z * scale.z);
}
